// #97 — the ESM half of the option-parity probe. Its CommonJS twin (`parity-cjs-dep`) runs the
// SAME probes through `require`, so every install option can be asserted on both interception
// paths in one process. Keep the two files behaviourally identical; a divergence between them
// would silently weaken the very comparison this pair exists to make.
//
// STATIC imports, deliberately: that is the shape M5's loader hook has to intercept before
// evaluation, and it is what binds `const` export bindings that can never be revisited (#62).
import { readFileSync } from "node:fs";
import { Socket } from "node:net";
import { fileURLToPath } from "node:url";

const DATA = fileURLToPath(new URL("./data.txt", import.meta.url));

/** One gated `fs` read. `OK` or the error's name — never a throw, so one denied probe cannot
 * abort the report the test parses. */
export function read() {
  try {
    return "OK:" + readFileSync(DATA, "utf8").trim();
  } catch (err) {
    return String(err && err.name);
  }
}

/** Hardened mode's observable on THIS path. The namespace object of an ESM module rejects
 * `[[Set]]` on its own, so the meaningful surface is the guarded class prototype — the one whose
 * un-freezing (#97) let `net.Socket.prototype.connect = evil` land under `hardened: true`. */
export function socketPrototypeFrozen() {
  return Object.isFrozen(Socket.prototype);
}

/** A read behind `depth` nested frames, for the `attribution.maxFrames` probe. */
export function readDeep(depth) {
  const call = depth <= 0 ? read : () => readDeep(depth - 1);
  return call();
}

/** The env guard's observable — a global, but probed from a dependency frame so the `<app>`
 * exemption does not apply. */
export function readEnv(key) {
  return process.env[key];
}

/** The global-egress guard's observable: whether `fetch` refuses an ungranted destination. */
export async function fetchProbe(url) {
  try {
    await fetch(url);
    return "OK";
  } catch (err) {
    return String(err && err.name);
  }
}
